/// Go for the Eyes. Cost 0. Deal `base_damage`; if the target currently
/// intends to attack, apply 1 Weak (2 upgraded).
///
/// C# `GoForTheEyes.OnPlay` (GoForTheEyes.cs:49) gates the Weak on
/// `cardPlay.Target.Monster.IntendsToAttack`, which `MonsterModel.cs:203-207`
/// defines as `IntentType.Attack || IntentType.DeathBlow`. The Rust attack
/// intents that map to those are [`Intent::Attack`] / [`Intent::MultiAttack`]
/// (both `IntentType.Attack` in C#) and [`Intent::DeathBlow`]. DeathBlow MUST
/// be included — exploder monsters (GasBomb &c.) telegraph it, and the engine's
/// own canonical attack-intent predicate (`combat_loop.rs`) already counts it.
/// A prior port mirrored the non-authoritative Python pin's `intent.is_attack`
/// and dropped DeathBlow, so the card applied 0 Weak against an exploder
/// telegraph.
pub(crate) fn play_go_for_the_eyes(
    state: &mut CombatState,
    target: Option<CreatureUid>,
) -> EffectResult {
    let t = target.expect("GoForTheEyes: Enemy-targeted");
    let base = current_card_damage(state);
    let _ = deal_damage_player_to_enemy(state, t, base);
    let intends_attack = state
        .creatures
        .iter()
        .find(|c| c.id == t.0)
        .and_then(|c| c.intent.as_ref())
        .is_some_and(|i| {
            matches!(
                i,
                Intent::Attack { .. } | Intent::MultiAttack { .. } | Intent::DeathBlow { .. }
            )
        });
    if intends_attack {
        // C# GoForTheEyes.cs: Weak BaseValue 1, +1 on upgrade -> 2. The prior
        // hardcoded 1 dropped the upgrade. Bead `sts2-rs-ah2kr`.
        let weak = if current_card_upgraded(state) { 2 } else { 1 };
        apply_power_to_enemy(state, t, PowerKind::Weak, weak);
    }
    EffectResult::Resolved
}

